const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const number=value=>{
  if(typeof value!=='number'||!Number.isFinite(value))return 'Unavailable';
  const magnitude=Math.abs(value);
  return new Intl.NumberFormat('en-US',magnitude!==0&&(magnitude<0.0001||magnitude>=1e9)?{notation:'scientific',maximumSignificantDigits:6}:{maximumFractionDigits:4}).format(value);
};
const exactPrice=value=>typeof value==='string'&&/^\d{1,15}(?:\.\d{1,12})?$/.test(value)&&/[1-9]/.test(value)?value:'Unavailable';
const headlinePrice=value=>exactPrice(value).split('.').map(part=>part.replace(/(\d{3})(?=\d)/g,'$1<wbr>')).join('.<wbr>');
const https=value=>{try{const url=new URL(value);return url.protocol==='https:'?url.href:null;}catch{return null;}};
const stamp=value=>typeof value==='string'&&Number.isFinite(Date.parse(value))?new Date(value).toISOString().replace('T',' ').replace('.000Z','Z').replace(/Z$/,' UTC'):'Unavailable';
const words=value=>String(value??'Unavailable').replaceAll('_',' ');
const external=(url,label)=>https(url)?`<a href="${escape(https(url))}" target="_blank" rel="noopener noreferrer">${escape(label)}<span class="sr-only"> (opens in a new tab)</span> ↗</a>`:'<span>Source link unavailable</span>';
const rows=values=>`<dl class="desk-facts">${values.map(([label,value])=>`<div><dt>${escape(label)}</dt><dd>${escape(value)}</dd></div>`).join('')}</dl>`;

function chart(points,currency,symbol){
  const min=Math.min(...points.map(point=>point.low)),max=Math.max(...points.map(point=>point.high));
  const spread=max-min||Math.max(Math.abs(max)*.01,1),floor=min===max?min-spread/2:min;
  const x=index=>points.length===1?360:12+index/(points.length-1)*696;
  const y=value=>224-(value-floor)/spread*208;
  const segments=[];let segment=[];
  for(let index=0;index<points.length;index++){
    if(points[index].breakBefore&&segment.length){segments.push(segment);segment=[];}
    segment.push(`${x(index).toFixed(2)},${y(points[index].close).toFixed(2)}`);
  }
  if(segment.length)segments.push(segment);
  const title=`${symbol} approximate daily closing-price plot`,description=`${points.length} supplied sessions, ${points[0].session} through ${points.at(-1).session}. ${currency} prices. Breaks mark missing sessions or corporate actions. Plot positions and axis labels are approximate. Supplied decimal prices follow in the data table.`;
  return `<figure class="price-figure"><div class="price-plot-layout"><div class="price-axis" aria-hidden="true"><span>${escape(number(max))}</span><span>${escape(number((max+min)/2))}</span><span>${escape(number(min))}</span></div><svg class="price-plot" viewBox="0 0 720 240" preserveAspectRatio="none" role="img" aria-labelledby="price-plot-title price-plot-description"><title id="price-plot-title">${escape(title)}</title><desc id="price-plot-description">${escape(description)}</desc><path class="price-grid" d="M0 16H720 M0 120H720 M0 224H720"/>${segments.map(segment=>segment.length===1?`<path class="price-line" d="M${segment[0]}h.1"/>`:`<polyline class="price-line" points="${segment.join(' ')}"/>`).join('')}</svg></div><div class="price-date-axis" aria-hidden="true"><span>${escape(points[0].session)}</span><span>${escape(points.at(-1).session)}</span></div><figcaption>Approximate daily close · ${escape(currency)} · ${points.length} supplied sessions</figcaption></figure>`;
}

function priceTable(points,currency,retained=false){
  return `<details class="desk-disclosure" data-state-key="prices:daily-values"><summary>Daily prices & volume</summary><div class="desk-table-scroll" tabindex="0" role="region" aria-label="Daily price values, scroll horizontally if needed"><table class="desk-table"><caption>${retained?'Retained':'Imported'} daily values · ${escape(currency)}</caption><thead><tr><th scope="col">Session</th><th scope="col">Open</th><th scope="col">High</th><th scope="col">Low</th><th scope="col">Close</th><th scope="col">Volume</th><th scope="col">Notes</th></tr></thead><tbody>${points.map(point=>`<tr><th scope="row">${escape(point.session)}</th>${['open','high','low','close'].map(key=>`<td>${escape(exactPrice(point.decimals?.[key]))}</td>`).join('')}<td>${escape(number(point.volume))}</td><td>${point.breakBefore?'Gap before this session. ':''}${Array.isArray(point.actions)&&point.actions.length?`${point.actions.length} corporate action${point.actions.length===1?'':'s'} recorded.`:''}</td></tr>`).join('')}</tbody></table></div></details>`;
}

function comparisonView(comparison,symbol){
  const available=comparison?.status==='available'&&Array.isArray(comparison.points)&&comparison.points.length>0&&comparison.points.every(point=>point&&Number.isFinite(point.targetIndex)&&Number.isFinite(point.benchmarkIndex));
  return `<details class="desk-disclosure" data-state-key="prices:comparison"><summary>Benchmark comparison</summary>${available?`<p>Indexed to 100 on the first shared session. Both series use the same dates, currency and price basis. Displayed index values are approximate. This describes the supplied history.</p><div class="desk-table-scroll" tabindex="0" role="region" aria-label="Indexed price comparison"><table class="desk-table"><caption>${escape(symbol)} and ${escape(comparison.benchmarkSymbol)} · ${escape(words(comparison.basis))}</caption><thead><tr><th scope="col">Session</th><th scope="col">${escape(symbol)}</th><th scope="col">${escape(comparison.benchmarkSymbol)}</th></tr></thead><tbody>${comparison.points.map(point=>`<tr><th scope="row">${escape(point.session)}</th><td>${escape(number(point.targetIndex))}</td><td>${escape(number(point.benchmarkIndex))}</td></tr>`).join('')}</tbody></table></div>`:`<p>Comparable benchmark history is unavailable.${comparison?.reason?` ${escape(words(comparison.reason))}.`:''}</p>`}</details>`;
}

/** Pure view. The host owns imports, selected symbols and the isolated widget.
 * options.symbolOptions: [{symbol,label}]; hosted: {status,url,symbol,message}.
 * Imported bars never establish evaluated prices or paper marks.
 */
export function renderPriceView(model=null,{symbol=model?.symbol||'',rangeSessions=20,symbolOptions=[],hosted={status:'idle'},feedback=null}={}){
  const available=!!model&&['available','partial'].includes(model.status)&&Array.isArray(model.points)&&model.points.length>0&&model.points.every(point=>point&&['open','high','low','close'].every(key=>typeof point[key]==='number'&&Number.isFinite(point[key]))&&typeof point.session==='string');
  const points=available?model.points:[],source=model?.source||{},freshness=model?.freshness||{},currency=model?.currency||'Currency unavailable';
  const capture={within_policy:'Within the capture-age policy',stale:'Source capture is stale',unknown:'Capture age unavailable',invalid:'Capture clock invalid'}[freshness.captureStatus]||'Capture age unavailable';
  const session={current_completed_session:'Latest completed session supplied',behind_completed_session:'Latest completed session missing',calendar_unknown:'Session-calendar coverage unknown'}[freshness.sessionStatus]||'Session-calendar coverage unknown';
  const choices=symbolOptions.length?symbolOptions:symbol?[{symbol,label:symbol}]:[];
  const retained=source.channel==='retained_capture';
  const providerURL=https(hosted.url)||'https://www.tradingview.com/chart/';
  return `<div class="price-desk utility-desk">
    <section class="desk-controls card" aria-label="Price chart selection"><form data-price-form="selection" class="desk-selection"><label for="price-symbol">Company<select id="price-symbol" name="symbol">${choices.map(choice=>`<option value="${escape(choice.symbol)}"${choice.symbol===symbol?' selected':''}>${escape(choice.label||choice.symbol)}</option>`).join('')}</select></label><label for="price-range">Imported history<select id="price-range" name="rangeSessions">${[20,60,120,'all'].map(range=>`<option value="${range}"${String(range)===String(rangeSessions)?' selected':''}>${range==='all'?'All supplied sessions':`${range} sessions`}</option>`).join('')}</select></label><button class="desk-button" type="submit">Show prices</button></form></section>
    ${feedback?`<p class="desk-feedback" role="status">${escape(feedback)}</p>`:''}
    <section class="card desk-panel hosted-price-panel" aria-labelledby="hosted-price-heading"><div class="desk-panel-heading"><div><span class="eyebrow">MARKET CHART</span><h2 id="hosted-price-heading">${escape(symbol||'Company')} price action</h2></div><span class="desk-badge">TradingView</span></div><p>Explore the hosted chart. Its displayed prices stay separate from the journal’s evaluated prices.</p><div id="hosted-price-chart" class="hosted-price-chart" data-hosted-status="${escape(hosted.status||'idle')}">${hosted.status==='ready'?'<p class="desk-muted">Hosted chart is ready.</p>':hosted.status==='loading'?'<p role="status">Loading the hosted chart…</p>':`<div class="desk-empty"><p>${hosted.status==='unavailable'?escape(hosted.message||'The hosted chart could not be loaded.'): 'Load a market chart for the selected company.'}</p><button class="desk-button" type="button" data-price-action="load-hosted">${hosted.status==='unavailable'?'Retry hosted chart':'Load hosted chart'}</button></div>`}</div><p class="desk-source">${external(providerURL,'Open chart at TradingView')} <span>NYSE and Nasdaq stock data may be delayed and use Cboe One coverage.</span></p></section>
    <section class="card desk-panel" aria-labelledby="imported-price-heading"><div class="desk-panel-heading"><div><span class="eyebrow">SUPPLIED DATA</span><h2 id="imported-price-heading">${retained?'Retained':'Imported'} daily prices</h2></div>${available?`<span class="desk-badge">${escape(words(model.priceBasis))}</span>`:''}</div>
      ${available?`<div class="price-value"><strong>${headlinePrice(points.at(-1).decimals?.close)}</strong><span>${escape(currency)} · close on ${escape(points.at(-1).session)}</span></div><p class="desk-notice">This dataset has not been verified for journal valuation. Paper marks remain unavailable.</p><div class="price-status-line"><span>${escape(capture)}</span><span>${escape(session)}</span></div>${chart(points,currency,symbol||model.symbol)}${model.gaps?.status!=='complete'?`<p class="desk-notice">${model.gaps?.status==='incomplete'?`${model.gaps.missingSessions?.length||0} expected sessions are missing. The line breaks at known gaps.`:'Calendar coverage is unknown; a continuous line does not prove complete session coverage.'}</p>`:''}${priceTable(points,currency,retained)}${comparisonView(model.comparison,symbol||model.symbol)}`:`<div class="desk-empty"><h3>${retained?'Retained price history unavailable':'No imported price history'}</h3><p>A source-backed daily dataset is needed before this panel can show prices.</p></div>`}
      <details class="desk-disclosure" data-state-key="prices:provenance"><summary>Source, timing & adjustments</summary>${rows([['Provider',source.provider||'Unavailable'],['Dataset',source.dataset||'Unavailable'],['Feed',source.feed||'Not specified'],['Price session',words(source.priceSession)],['Volume session',words(source.volumeSession)],['Symbol reference date',source.symbolAsOf||'Not specified'],['Captured at',stamp(source.capturedAt)],['Published at',stamp(source.publishedAt)],['Capture state',capture],['Session coverage',session],['Expected latest session',freshness.expectedLatestSession||'Unavailable'],['Declared delay',Number.isFinite(freshness.declaredDelayMinutes)?`${freshness.declaredDelayMinutes} minutes`:'Not specified'],['Price basis',words(model?.priceBasis)],['Volume basis',words(model?.volumeBasis)],['Review state',words(model?.chartTrust)],['Paper marks','Unavailable']])}<p class="desk-source">${external(source.url,'Open data source')}</p>${model?.warnings?.length?`<ul>${model.warnings.map(item=>`<li>${escape(words(item))}</li>`).join('')}</ul>`:''}${model?.issues?.length?`<ul>${model.issues.map(item=>`<li>${escape(words(item))}</li>`).join('')}</ul>`:''}</details>
      <details class="desk-disclosure" data-state-key="prices:import"><summary>Import daily price data</summary><p>Choose canonical Cribscore price JSON (up to 2 MiB), including source, capture time and adjustment basis. A valid import replaces all currently imported datasets. Data stays only in this tab and is cleared on reload. Keep your original file. Imported values do not become verified journal prices.</p><p><a href="./help/price-import.html" target="_blank" rel="noopener noreferrer">JSON format guide and example<span class="sr-only"> (opens in a new tab)</span> ↗</a></p><form data-price-form="import" class="desk-form"><label for="price-import-file">Price dataset<input id="price-import-file" name="file" type="file" accept=".json,application/json" required></label><button class="desk-button" type="submit">Import price data</button></form></details>
    </section>
  </div>`;
}
